  "about.badge": "About",
  "about.title": "Built for legal teams who value clarity",
  "about.subtitle":
    "CaseDex is a structured case workspace purpose-built for legal professionals, chambers, and law students in Bangladesh. It brings hearings, diary entries, client records, documents, and AI-assisted research into a single, organized environment — so your team spends less time searching and more time preparing.",
  "about.body1":
    "We believe legal work demands focus, not friction. CaseDex is designed around trust, calm workflows, and consistent structure. The interface is intentionally minimal — neutral tones, clean typography, and no unnecessary distractions — so you can concentrate on the substance of your cases. Every feature is built to mirror how lawyers actually work: from case intake and hearing preparation to document management and team coordination.",
  "about.body2":
    "CaseDex is a workspace tool, not a legal advisor. It helps you organize, summarize, and track — but every summary is editable, every note is yours to review, and professional judgment always stays with you. We support your practice; we never replace it.",
  "about.card1.title": "Structured by design",
  "about.card1.desc": "Every module — cases, hearings, diary, documents, contacts — mirrors real legal workflows. No learning curve, no unnecessary abstraction. The workspace works the way you already think about your cases.",
  "about.card2.title": "Editable AI summaries",
  "about.card2.desc": "AI-generated hearing summaries, diary rewrites, and research notes are always presented as drafts. You review, edit, and approve before anything is saved. The AI assists your memory — it never overrides your judgment.",
  "about.card3.title": "Firm-level isolation",
  "about.card3.desc":
    "Every firm, chamber, or organization operates in a completely isolated environment. Your cases, documents, and team data are invisible to other firms. Data isolation is enforced at the database level, not just the application layer.",
  "about.card4.title": "Calm, focused interfaces",
  "about.card4.desc":
    "Legal work is stressful enough. CaseDex uses neutral colors, measured typography, and generous whitespace to create a workspace that feels professional and composed — whether you are preparing for a hearing at 2 AM or reviewing case notes between court sessions.",
