  "security.badge": "Security",
  "security.title": "Security and compliance",
  "security.subtitle":
    "CaseDex is built with security at every layer. We use firm-level isolation, encryption, audit logging, and signed access controls to protect your confidential legal data — because trust is the foundation of legal practice.",
  "security.card1.title": "Firm-level isolation",
  "security.card1.desc":
    "Every database query is scoped to your firm's boundary. Cases, documents, contacts, and team data belonging to one firm are completely invisible to another. This isolation is enforced at the infrastructure level through row-level policies — not just application logic.",
  "security.card2.title": "Comprehensive audit logging",
  "security.card2.desc":
    "Every significant action is recorded: logins, case creation and updates, document uploads and downloads, team member changes, and permission modifications. Audit logs are immutable and available for compliance review, giving your firm a clear trail of who did what and when.",
  "security.card3.title": "Signed document access",
  "security.card3.desc":
    "Documents are never served through publicly accessible URLs. Every download generates a time-limited, cryptographically signed link that expires after use. This ensures that only authenticated, authorized users can access sensitive filings, court orders, and evidence.",
  "security.card4.title": "Rate limiting and abuse prevention",
  "security.card4.desc":
    "Authentication endpoints, API routes, and AI features are protected by rate limiting to prevent brute-force attacks and abuse. Suspicious activity patterns trigger automatic throttling to protect your account.",
  "privacy.badge": "Privacy",
  "privacy.title": "Privacy policy",
  "privacy.subtitle":
    "CaseDex is built to protect the confidentiality of your legal work. We treat your case data, client records, and professional communications with the same seriousness you do. This policy explains what we collect, how we use it, and the controls you have over your information.",
  "privacy.card1.title": "What we collect",
  "privacy.card1.desc":
    "We collect information necessary to operate your workspace: your name, email address, organization details, and the case data you create (cases, hearings, diary entries, documents, contacts). We also collect usage analytics (page views, feature usage) to improve the platform. We do not collect data from your device beyond what the browser provides, and we do not use tracking cookies for advertising.",
  "privacy.card2.title": "Firm data boundaries",
  "privacy.card2.desc":
    "All data is strictly isolated per firm. Your cases, documents, client records, and team information are stored in a dedicated scope that is invisible to other organizations on the platform. Even CaseDex support staff access firm data only with explicit permission and only for troubleshooting purposes.",
  "privacy.card3.title": "We never sell your data",
  "privacy.card3.desc": "We do not sell, rent, or share your personal information, case data, or client records with third parties for marketing or any other commercial purpose. Your data exists solely to power your workspace. Period.",
  "privacy.card4.title": "Security controls",
  "privacy.card4.desc": "We protect your data with multiple layers of security: TLS 1.3 encryption in transit, AES-256 encryption at rest, signed document download URLs, comprehensive audit logging, and role-based access controls. See our Security page for full technical details.",
  "terms.badge": "Terms",
  "terms.title": "Terms of service",
  "terms.subtitle":
    "By using CaseDex, you agree to these terms. Please read them carefully. These terms govern your use of the CaseDex platform, including all features, services, and content provided through casedex.app.",
  "terms.card1.title": "No legal advice",
  "terms.card1.desc":
    "CaseDex is a case management and workspace tool. It does not provide legal advice, legal opinions, or legal representation. No attorney-client relationship is created between you and CaseDex. AI-generated content (summaries, rewrites, research answers) is provided as draft assistance only. You are solely responsible for exercising professional judgment in all legal matters.",
  "terms.card2.title": "User responsibility",
  "terms.card2.desc":
    "You are responsible for the accuracy and completeness of all information you enter into CaseDex. You must ensure that your use of the platform complies with applicable laws, bar council rules, and professional ethics obligations. You are responsible for maintaining the confidentiality of your login credentials and for all activity under your account.",
  "terms.card3.title": "Acceptable use",
  "terms.card3.desc":
    "You agree to use CaseDex only for lawful purposes related to legal practice, education, or case management. You must not attempt to access other firms' data, reverse-engineer the platform, use automated scraping tools, or upload malicious content. Violation of these terms may result in immediate account suspension.",
  "terms.card4.title": "Account and access",
  "terms.card4.desc":
    "Access is limited to authorized users within your firm. Account administrators control team membership and permissions. CaseDex reserves the right to suspend or terminate accounts that violate these terms, engage in abusive behavior, or fail to maintain an active subscription after the trial period.",
  "footer.title": "CaseDex",
  "footer.subtitle":
    "A structured case workspace for legal professionals and law students.",
  "footer.note": "CaseDex assists memory, not decisions.",
  "footer.product": "Product",
  "footer.company": "Company",
